mapper.select:
/*selectCalendarGridList CALENDAR LIST*/ WITH mgmtCalendarListPage AS( SELECT * from(SELECT * FROM ( SELECT ROWNUM RNUM ,A.* FROM( SELECT CALENDAR_DIV ,TITLE ,CONTENT ,DESK_DIV ,TITLE || CONTENT AS SEARCH_KEYWORD ,TO_DATE(START_TIME, 'YYYY-MM-DD HH24:MI:SS') AS START_TIME ,TO_DATE(END_TIME, 'YYYY-MM-DD HH24:MI:SS') AS END_TIME ,ALLDAY_DIV AS ALLDAY ,BG_COLOR AS BACKGROUNDCOLOR ,BORDER_COLOR AS BORDERCOLOR ,STATUS_CD ,CHECK_DATE ,CHECK_YN ,MODIFY_USER ,MODIFY_DATE ,CREATE_USER AS EVENT_USER ,CREATE_DATE ,COUNT(*) OVER() TOTAL_COUNT FROM TB_C_CALENDAR WHERE SUBSTR(START_TIME,0,10) BETWEEN #{in_startDate} AND #{in_endDate}
AND SYSTEM_DIV = #{sel_system}
AND STATUS_CD = #{sel_status}
ORDER BY START_TIME )A WHERE SEARCH_KEYWORD LIKE ('%${search_keyword}%') )WHERE RNUM <= ${totalPagesize} ) WHERE RNUM > ${currentPageSize} ) select * from mgmtCalendarListPage

mapper.insert:
/*TB_M_CALENDAR*/
	INSERT INTO TB_C_CALENDAR(
					CALENDAR_SEQ
		           ,CALENDAR_DIV
		           ,STATUS_CD
		           ,TITLE
		           ,CONTENT
		           ,DESK_DIV
		           ,CHECK_YN
		           ,CHECK_DATE
		           ,START_TIME
		           ,END_TIME
		           ,ALLDAY_DIV
		           ,BG_COLOR
		           ,BORDER_COLOR           
		           ,MODIFY_DATE
		           ,MODIFY_USER
		           ,CREATE_DATE
		           ,CREATE_USER
	           )VALUES(
	           		calendar_sequence.nextval
		           ,#{in_calendarDiv}
		           ,'C'
		           ,#{in_title}
		           ,#{in_content}
		           ,#{in_deskDiv}
		           ,'Y'
		           ,TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS')
		           ,#{in_startDate}
		           ,#{in_endDate}
		           ,#{in_allDay}
		           ,#{in_color}
		           ,#{in_color}
		           ,SYSDATE
		           ,#{in_userId}
		           ,SYSDATE
		           ,#{in_userId}
	           )

mapper.update:
  		UPDATE TB_C_CALENDAR
  		   SET  TITLE = #{in_title}
		       ,CALENDAR_DIV = #{in_calendarDiv}
		       ,CHECK_YN = 'Y'
		       ,CHECK_DATE = TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS')
		       ,CONTENT = #{in_content}
		       ,DESK_DIV = #{in_deskDiv}
		       ,BG_COLOR = #{in_color}
		       ,START_TIME = #{in_startDate}
		       ,END_TIME =	#{in_endDate}
		       ,BORDER_COLOR = #{in_color}
		       ,MODIFY_USER =  #{in_userId}
		       ,MODIFY_DATE =  SYSDATE
  		 WHERE TO_CHAR(CREATE_DATE, 'YYYY-MM-DD HH24:MI:SS') = #{in_createDate}

mapper.delete:
		DELETE
		FROM TB_C_CALENDAR
		WHERE TO_CHAR(CREATE_DATE, 'YYYY-MM-DD HH24:MI:SS') = #{in_createDate}
       	AND CREATE_USER = #{in_createrId}
